flowchart TD
  P[Problem spotted] --> Q1{"Affects more than<br/>one team?"}
  Q1 -->|no| C["Coach a Senior<br/>to own it"]
  Q1 -->|yes| Q2{"Tied to an<br/>org priority?"}
  Q2 -->|no| K["Park it,<br/>revisit next half"]
  Q2 -->|yes| Q3{"Someone already<br/>owns it?"}
  Q3 -->|yes| S["Support and<br/>unblock them"]
  Q3 -->|no| Q4{"Needs a decision<br/>or execution?"}
  Q4 -->|decision| D["Write doc,<br/>drive alignment"]
  Q4 -->|execution| L["Lead it,<br/>then hand off"]
